use super::UnassignedUpid;

/// A USLP Protocol Identifier, typed by the SANA registry (732.1 §4.1.4.2.3; USLP-007).
///
/// Each named variant is a value the registry assigns, with the registry's description;
/// every other 5-bit value is [`Upid::Other`] and decodes like any other (USLP-007).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Upid {
    /// `00000`: Space Packets or Encapsulation packets are contained within the TFDZ. (SANA
    /// \[ccsds-732.1-B-1\], OID 1.3.112.4.58.1)
    Packets,
    /// `00001`: COP-1 Control Commands are contained within the TFDZ. (SANA \[ccsds-732.1-B-1\],
    /// OID 1.3.112.4.58.2)
    Cop1ControlCommands,
    /// `00010`: COP-P Control Commands are contained within the TFDZ. (SANA \[ccsds-732.1-B-1\],
    /// OID 1.3.112.4.58.3)
    CopPControlCommands,
    /// `00100`: User-defined Octet Stream data are contained within the TFDZ. (SANA
    /// \[ccsds-732.1-B-1\], OID 1.3.112.4.58.5)
    OctetStream,
    /// `00101`: Mission-specific Information-1 as a MAPA_SDU or VCA_SDU is contained within the
    /// TFDZ. (SANA \[ccsds-732.1-B-1\], OID 1.3.112.4.58.6)
    MissionSpecificInformation1,
    /// `00110`: Proximity-1 Pseudo Packet Identifier 1 for Segmentation (SANA \[ccsds-732.1-B-1\],
    /// OID 1.3.112.4.58.9)
    Proximity1PseudoPacketId1,
    /// `00111`: Proximity-1 Supervisory Protocol Data Units (SPDUs) are contained within the TFDZ.
    /// (SANA \[ccsds-732.1-B-1\], OID 1.3.112.4.58.7)
    Proximity1Spdus,
    /// `01000`: Proximity-1 Pseudo Packet Identifier 2 for Segmentation (SANA \[ccsds-732.1-B-1\],
    /// OID 1.3.112.4.58.10)
    Proximity1PseudoPacketId2,
    /// `11111`: UPID field signals that the entire fixed-length TFDZ contains idle data. (SANA
    /// \[ccsds-732.1-B-1\], OID 1.3.112.4.58.8)
    OnlyIdleData,
    /// A value the registry does not assign (USLP-007).
    Other(UnassignedUpid),
}

impl Upid {
    /// The UPID of a 5-bit field value, or `None` above 31 (732.1 §4.1.4.2.3.1; USLP-007).
    #[must_use]
    pub const fn from_bits(bits: u8) -> Option<Upid> {
        match bits {
            0b00000 => Some(Upid::Packets),
            0b00001 => Some(Upid::Cop1ControlCommands),
            0b00010 => Some(Upid::CopPControlCommands),
            0b00100 => Some(Upid::OctetStream),
            0b00101 => Some(Upid::MissionSpecificInformation1),
            0b00110 => Some(Upid::Proximity1PseudoPacketId1),
            0b00111 => Some(Upid::Proximity1Spdus),
            0b01000 => Some(Upid::Proximity1PseudoPacketId2),
            0b11111 => Some(Upid::OnlyIdleData),
            _ => match UnassignedUpid::new(bits) {
                Some(u) => Some(Upid::Other(u)),
                None => None,
            },
        }
    }

    /// The 5-bit field value (732.1 §4.1.4.2.3.1; USLP-007).
    #[must_use]
    pub const fn bits(self) -> u8 {
        match self {
            Upid::Packets => 0b00000,
            Upid::Cop1ControlCommands => 0b00001,
            Upid::CopPControlCommands => 0b00010,
            Upid::OctetStream => 0b00100,
            Upid::MissionSpecificInformation1 => 0b00101,
            Upid::Proximity1PseudoPacketId1 => 0b00110,
            Upid::Proximity1Spdus => 0b00111,
            Upid::Proximity1PseudoPacketId2 => 0b01000,
            Upid::OnlyIdleData => 0b11111,
            Upid::Other(u) => u.get(),
        }
    }
}

/// Whether the registry assigns `bits` (USLP-007).
pub(crate) const fn is_assigned(bits: u8) -> bool {
    matches!(
        bits,
        0b00000 | 0b00001 | 0b00010 | 0b00100 | 0b00101 | 0b00110 | 0b00111 | 0b01000 | 0b11111
    )
}
